// Schnellprüfung vieler Seiten nacheinander in einem Browser:
// HTTP-Status, Konsolenfehler, horizontaler Überlauf, Bild des oberen Bildschirms.
// Aufruf: node check.mjs <basis-url> <ausgabeordner> <breiten> <pfad1> <pfad2> ...
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";

const [basis, out, breitenArg, ...pfade] = process.argv.slice(2);
mkdirSync(out, { recursive: true });
const browser = await chromium.launch();
const ctx = await browser.newContext();
// Cookie-Banner vorab wegklicken, indem wir es einmal schließen
let bannerZu = false;

for (const w of breitenArg.split(",").map(Number)) {
  const page = await ctx.newPage();
  await page.setViewportSize({ width: w, height: w < 700 ? 844 : 900 });
  for (const pfad of pfade) {
    const fehler = [];
    const onC = (m) => m.type() === "error" && fehler.push(m.text());
    const onE = (e) => fehler.push(String(e));
    page.on("console", onC);
    page.on("pageerror", onE);
    let status = 0;
    try {
      const r = await page.goto(basis + pfad, { waitUntil: "load", timeout: 180000 });
      status = r ? r.status() : 0;
      await page.waitForTimeout(1500);
      if (!bannerZu) {
        await page.locator("button", { hasText: "Nur notwendige" }).first().click({ timeout: 4000 }).then(() => { bannerZu = true; }).catch(() => {});
      }
      const breite = await page.evaluate(() => document.documentElement.scrollWidth);
      const overlay = await page.locator("nextjs-portal").count();
      const name = pfad.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "") || "start";
      await page.screenshot({ path: `${out}/w${w}-${name}.png` });
      const ok = status === 200 && breite <= w && fehler.length === 0;
      console.log(`${ok ? "OK  " : "!!  "} w${w} ${pfad}  status=${status} breite=${breite}${breite > w ? " ÜBERLAUF" : ""} fehler=${fehler.length}${overlay ? " (Dev-Overlay)" : ""}`);
      fehler.slice(0, 3).forEach((f) => console.log("       ! " + f.slice(0, 180)));
    } catch (e) {
      console.log(`!!   w${w} ${pfad}  LADEFEHLER ${String(e).slice(0, 120)}`);
    }

// GET /api/land – Ländervorschlag (Welle 2, Masterplan Abschnitt 4)
//
// Liefert NUR einen Vorschlag aus Accept-Language bzw. dem Länder-Header des Hostings.
// Keine Weiterleitung, kein Cookie, kein Vary auf Geo-Header, nie zwischenspeichern.
// Das Client-Banner (src/components/Land/LaenderHinweis.js) zeigt daraus einen schließbaren Hinweis.
import { NextResponse } from "next/server";
import { GEO_HEADER, landVorschlag } from "@/lib/land";

export const dynamic = "force-dynamic";

export function GET(request) {
  const geo = GEO_HEADER.map((h) => request.headers.get(h)).find(Boolean) || null;
  const ergebnis = landVorschlag({ acceptLanguage: request.headers.get("accept-language"), geo });
  return NextResponse.json(ergebnis, { headers: { "Cache-Control": "private, no-store", "X-Robots-Tag": "noindex" } });
}
// GET /p/<kennung>?z=<pfadschlüssel> – Kurzlink für offengelegte Gruppen- und Partnerverweise (Welle 2, Paket GRP)
//
//  - 302 auf ein INTERNES, freigegebenes Ziel mit utm_source=<kennung>&utm_medium=gruppe|partner.
//    Ziele nur aus der Positivliste (Pfadschlüssel in src/lib/gruppe/partner-register.js → ZIELE und je Eintrag
//    `ziele`), zusätzlich durch sicheresZiel() (kein offener Redirect). Location ist ein relativer Pfad – kein
//    Host-Header-Vertrauen.
//  - Unbekannte, formal ungültige oder (in Produktion) Entwurfs-Kennungen → Startseite OHNE Parameter.
//  - Kein Cookie, kein Versand, kein Logging der Kennung, kein Zähler mit Personenbezug.
//  - Land: über `?l=DE|AT|CH` überschreibbar (nur Register-Länder), sonst das Land des Eintrags. Ziel je Land über
//    src/lib/land (Länderrouting aktiv, Welle 2); "start" = Einstieg des Landes (/de, /at, /ch).

import { kennungFinden, mediumFuerArt, REGISTER_LAENDER, zielPfad } from "@/lib/gruppe/partner-register";
import { sicheresZiel } from "@/lib/plattform/client";

const KOPF = {
  "Cache-Control": "no-store",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "X-Robots-Tag": "noindex, nofollow",
};

const weiter = (ziel) => new Response(null, { status: 302, headers: { ...KOPF, Location: ziel } });

/** Ziel für eine Kennung berechnen (Tests über GET: src/lib/gruppe/kurzlink.test.mjs). */
function kurzlinkZiel(kennung, suche) {
  const eintrag = kennungFinden(kennung);
  if (!eintrag) return "/";
  const schluessel = suche.get("z") || "start";
  const erlaubt = eintrag.ziele?.includes(schluessel) ? schluessel : "start";
  const landWunsch = String(suche.get("l") || "").toUpperCase();
  const land = REGISTER_LAENDER.includes(landWunsch) ? landWunsch : eintrag.land;
  const pfad = zielPfad(erlaubt, land) || "/";
  const sicher = sicheresZiel(pfad, "/");
  if (sicher !== pfad) return "/";
  const q = new URLSearchParams({ utm_source: eintrag.kennung, utm_medium: mediumFuerArt(eintrag.art) });
  return `${sicher}?${q}`;
}

export async function GET(request, { params }) {
  const { kennung } = (await params) || {};
  let suche;
  try {
    suche = new URL(request.url).searchParams;
  } catch {
    suche = new URLSearchParams();
  }
  return weiter(kurzlinkZiel(typeof kennung === "string" ? decodeURIComponentSicher(kennung) : "", suche));
}

export const HEAD = GET;

function decodeURIComponentSicher(s) {
  try {
    return decodeURIComponent(s);
  } catch {
    return "";
  }
}

